// Тикет #1cf95182 · 1cf9518294d3d368ce75afe6 «תזכורות מהירות» RTL (Figma 436:1292) — עבר QA 14.10.2026 (iPhone, TestFlight 1.0.0 (20), вход клиента).
// Кейс .qa/tests/reminders/RM-10-quick-reminders-rtl.md.
// מה רצוי: «בכרטיסי «תזכורות מהירות» האייקון בצד ימין, והכותרת והטקסט מיושרים לימין, צמודים לאייקון (כמו «הנחת תפילין / אל תשכח להניח היום עד השקיעה»).»
// Факт 14.10 12:47: при включённом «תזכורות במערכת» карточки «מנחה / אפשר להתפלל מ־12:55 עד 18:10», «הנחת תפילין / אל תשכח להניח היום עד השקיעה»,
//   «תאריך חשוב / היום - בדיקת QA» — заголовок и текст справа, вплотную к иконке (1cf95182-ios-b20-quick-reminders-rtl.png).
//   Набор карточек зависит от дня/времени — проверяются все видимые.
// @data: включает «תזכורות במערכת» в профиле, если выключен, и в конце возвращает исходное состояние (14.10: ВКЛ → ВЫКЛ).
// Нажатия — только по элементам (тумблер — по подписи).
import { driver, expect } from '@wdio/globals';
import { byText, scrollToText } from '../../helpers/ui.ts';
import { toHome } from '../../helpers/app.ts';
import { shown } from '../_lib/app-0710.ts';
import { rectOf, staticText } from '../_lib/app-1310.ts';
import { openProfileReminders, sysRemindersOn, toggleSysReminders } from '../_lib/app-1310b.ts';
import { visibleTexts } from '../_lib/app-1410.ts';

const OFF_TEXT = 'התזכורות כבויות — אפשר להפעיל בפרופיל';
const SKIP = new Set(['תזכורות מהירות', 'ניהול תזכורות', 'תאריכים חשובים']);
let switchedOn = false;

describe('«תזכורות מהירות» RTL (#1cf95182)', () => {
  after(async () => {
    if (!switchedOn) return;
    await openProfileReminders();
    if (await sysRemindersOn()) await toggleSysReminders();   // вернуть «выкл», как было
    await toHome().catch(() => {});
  });

  it('RM-10 Карточки «תזכורות מהירות»: заголовок и текст справа, вплотную к иконке #1cf95182 @data', async () => {
    // 1. Профиль: «תזכורות במערכת» включён (иначе включить и запомнить, чтобы вернуть).
    await openProfileReminders();
    if (!(await sysRemindersOn())) { await toggleSysReminders(); switchedOn = true; }

    // 2. Главная → блок «תזכורות מהירות».
    await toHome();
    await scrollToText('ניהול תזכורות');
    await expect(byText(OFF_TEXT)).not.toBeDisplayed();

    // 3. Тексты карточек между заголовком блока и «תאריכים חשובים»/нижней навигацией.
    const { width, height } = await driver.getWindowSize();
    const head = staticText('תזכורות מהירות');
    const y0 = (await shown(head)) ? (await rectOf(head)).y + 30 : 140;
    const next = staticText('תאריכים חשובים');
    const y1 = (await shown(next)) ? (await rectOf(next)).y : height * 0.87;
    const texts = (await visibleTexts((l, r) => !SKIP.has(l.trim()) && r.y >= y0 && r.y + r.height <= y1 && l.trim().length > 0));
    console.log(`[RM-10] тексты карточек: ${JSON.stringify(texts.map((t) => ({ l: t.label, x: Math.round(t.r.x), w: Math.round(t.r.width) })))}`);
    if (texts.length === 0) {
      console.log('[RM-10] тексты карточек не отдаются отдельными элементами (склеенная подпись) — @manual-check по скрину 1cf95182-ios-b20-quick-reminders-rtl.png');
      return;
    }
    // 14.10: правый край текста ≈ 0.74 ширины экрана (иконка — справа от текста). Прижатый влево текст (баг) — правый край < 0.5.
    let measured = 0;
    for (const t of texts) {
      if (t.r.width >= width * 0.6) continue;   // рамка почти на всю ширину — позиция букв не видна
      measured++;
      expect({ text: t.label, rightAligned: t.r.x + t.r.width >= width * 0.62 }).toEqual({ text: t.label, rightAligned: true });
      expect({ text: t.label, besideIcon: t.r.x + t.r.width <= width * 0.9 }).toEqual({ text: t.label, besideIcon: true });
    }
    if (measured === 0) console.log('[RM-10] все рамки текстов на всю ширину — выравнивание @manual-check');
  });
});
